import json
def evaluate(data, score, audit, fixed):
    tasks=[]; responses=[]; details=[]
    for s in data["scenes"]:
        for i,cue in enumerate(s["cues"]):
            tasks.append({"id":f'{s["id"]}-{i+1}',"category":"phone_ai_stage","kind":"continuation","prompt":cue,"any_of":[s["anchor"]],"cue_ack_any_of":s["cue_terms"][i],"action_any_of":["押します","たまりました","発行","適用","確保","分けました","設置","締めました","空けました","作りました","配りました","入室","作成","撮っています","お渡し","登録","複製"],"forbidden":data["forbidden"],"max_chars":data["max_chars"],"max_questions":0})
            for v in s["variants"]:
                responses.append({"task_id":f'{s["id"]}-{i+1}',"candidate":v["id"],"response":v["lines"][i]})
    index={t["id"]:t for t in tasks}
    format_result=lambda rows:sum(not score(index[r["task_id"]],r["response"]) for r in rows)
    original_audit=audit(tasks,responses)
    swapped=[]
    for s in data["scenes"]:
        for v,other in [(s["variants"][0],s["variants"][1]),(s["variants"][1],s["variants"][0])]:
            for i in range(3):
                line=other["lines"][i] if i==2 else v["lines"][i]
                swapped.append({"task_id":f'{s["id"]}-{i+1}',"candidate":v["id"],"response":line})
            original=v["lines"][2]
            foreign=other["lines"][2]
            history=" ".join(v["lines"][:2])
            assert v["state"] in history and other["state"] not in history
            rule=lambda line: v["state"] in line and other["state"] not in line
            details.append({"scene":s["id"],"candidate":v["id"],"expected_state":v["state"],"foreign_state":other["state"],"original":rule(original),"swapped":rule(foreign),"original_text":original,"swapped_text":foreign})
    swapped_audit=audit(tasks,swapped)
    # Fixed stage tasks are synthetic contract checks, never model runs.
    contract=[]
    for t in fixed:
        positive=t.get("expected_exact","")
        negative=positive+"追加の質問です。"
        contract.append({"task":t["id"],"positive_accepted":not score(t,positive),"negative_rejected":bool(score(t,negative))})
    return {"original_format":format_result(responses),"swapped_format":format_result(swapped),"original_lexical":original_audit["passed"],"swapped_lexical":swapped_audit["passed"],"original_count":len(responses),"swapped_count":len(swapped),"changed_final_count":len(details),"original_state_pass":sum(x["original"] for x in details),"swapped_state_rejected":sum(not x["swapped"] for x in details),"state_details":details,"original_lexical_failures":[x for x in original_audit["items"] if x["gate"]!="PASS"],"swapped_lexical_failures":[x for x in swapped_audit["items"] if x["gate"]!="PASS"],"fixed_contract":contract,"humor":"NOT_MEASURED","voice":"NOT_MEASURED","human_evaluation_count":0}
